index 35648de5..8e57e7c0 100644
--- a/HorseMod/CMakeLists.txt
+++ b/HorseMod/CMakeLists.txt
@@ -460,8 +460,31 @@ if(HORSEMOD_BUILD_PINNED_GEKKONET AND TARGET GekkoNet)
